// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzBlockNumber, uint256 fuzzTimestamp) public {
        vm.assume(fuzzBlockNumber > 0);
        vm.assume(fuzzTimestamp > 0);
        vm.roll(fuzzBlockNumber);
        vm.warp(fuzzTimestamp);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");
        if (fuzzBlockNumber % 15 == 0) {
            assertEq(address(c).balance, 0, "Balance should be zero after transfer when block.number % 15 == 0");
        } else {
            assertEq(address(c).balance, 10 ether, "Balance should remain when no transfer occurs");
        }
    }
}
